CH = dict(num=13, tag="Maths (Part 2)", theme="Linear equations in two variables, slope, pair of equations, substitution, elimination and graphical methods",
 title="Two Variables, One Line",
 intro="A single equation with two unknowns has endless solutions that lie on a straight line. Two such equations together can meet at one point, never meet, or lie on top of each other. This chapter shows how to read a line's slope, how to solve a pair by substitution, elimination and graphs, and how to predict the answer from the coefficients alone.",
 big_questions=["What does the solution of a linear equation in two variables look like?", "What is the slope of a line and what does it tell us?", "How do we solve a pair of linear equations and how many solutions can it have?"],
 blocks=[
 ("h2", "Linear Equations in Two Variables"),
 ("note", "DEFINITION", "An equation that can be written as **ax + by + c = 0**, where a, b, c are real numbers and **a and b are not both zero**, is a **linear equation in two variables**. This is its **standard form**."),
 ("ul", ["Example: mangoes ₹60/kg and bananas ₹50/kg with total ₹280 gives **60x + 50y = 280**.", "Coefficients can be fractions, but we usually multiply through to get **integer coefficients** (¼x + ⅗y − 2 = 0 becomes 5x + 12y − 40 = 0 after multiplying by 20).", "x + 7 = 0 is also linear in two variables: write it as **1·x + 0·y + 7 = 0**."]),
 ("table", ["Equation", "Standard form", "a", "b", "c"], [["3y = 5x − 7", "5x − 3y − 7 = 0", "5", "−3", "−7"], ["x = 8", "x + 0y − 8 = 0", "1", "0", "−8"], ["3y = 1", "0x + 3y − 1 = 0", "0", "3", "−1"]]),
 ("h2", "Solutions and Their Graph"),
 ("p", "A **solution** is an **ordered pair (x, y)** that satisfies the equation; the order matters because the first number is the x-value. For 3x + 2y = 12, (2, 3) and (4, 0) are solutions, but (1, 3) is not because 3 + 6 = 9 ≠ 12."),
 ("ul", ["Choose any value of x, substitute and solve for y: there are **infinitely many solutions**.", "Plotting the solutions gives a **straight line**; every point of the line is a solution and every solution is a point of the line.", "Quick way to draw it: put **x = 0** to get the y-intercept point, and **y = 0** to get the x-intercept point, then join them."]),
 ("table", ["Equation", "x = 0", "y = 0"], [["2x + y = 7", "(0, 7)", "(3.5, 0)"], ["4x + 3y = 12", "(0, 4)", "(3, 0)"], ["2x + 5y = 0", "(0, 0)", "(0, 0), so take x = 5 → (5, −2)"]]),
 ("note", "IMPORTANT", "If **c = 0**, then x = 0, y = 0 satisfies ax + by = 0, so the line **passes through the origin**. Multiplying an equation by a non-zero number does not change its solutions: 3x + 4y = 7 and 6x + 8y = 14 have the same solution set."),
 ("h3", "Finding unknown constants"),
 ("p", "If (−3, 4) is a solution of 3ax + 4y = −2, substitute: −9a + 16 = −2, so **a = 2**. Substituting a known solution turns the equation into an equation in the unknown constant."),
 ("h2", "Slope of a Line"),
 ("p", "The **slope** (gradient) measures how steep a line is. Take two points A(x₁, y₁) and B(x₂, y₂) on the line; the horizontal change is the **run** and the vertical change is the **rise**."),
 ("note", "FORMULA", "**Slope m = rise ÷ run = (y₂ − y₁) ÷ (x₂ − x₁)**. It is the same for any two points of the line and does not depend on the order in which the points are taken."),
 ("ul", ["Line through (2, 0) and (4, 3): slope = 3/2.", "Line through (−4, 5) and (−1, 2): slope = (2 − 5)/(−1 + 4) = **−1**.", "A ramp rising 2.5 m over a run of 4 m has slope 2.5/4 = 5/8."]),
 ("table", ["Slope", "How the line looks", "Example"], [["Positive (m > 0)", "Rises left to right", "y = 2x + 1"], ["Negative (m < 0)", "Falls left to right", "y = −3x + 4"], ["Zero", "Horizontal, parallel to x-axis", "y = 5"], ["Undefined (run = 0)", "Vertical, parallel to y-axis", "x = 2"]]),
 ("h2", "Slope-Intercept Form"),
 ("note", "FORMULA", "**y = mx + d** where **m** is the slope and **d** is the y-intercept (the line crosses the y-axis at (0, d))."),
 ("ul", ["Why m is the slope: for points on y = mx + d, (mx₂ + d) − (mx₁ + d) = m(x₂ − x₁), so rise ÷ run = m.", "From ax + by + c = 0 with b ≠ 0: **y = −(a/b)x − c/b**, so **m = −a/b** and **d = −c/b**.", "Example: 5x + y = 3 → y = −5x + 3: slope −5 (y falls 5 for each 1 step in x), intercept 3.", "Two lines with the **same slope** and different intercepts are **parallel**."]),
 ("h2", "Pair of Linear Equations"),
 ("p", "Two linear equations in the same two variables form a **pair**: a₁x + b₁y + c₁ = 0 and a₂x + b₂y + c₂ = 0. A **solution of the pair** is an ordered pair that satisfies **both** equations, i.e. a point lying on both lines."),
 ("ul", ["Framing: 2 adult + 3 child tickets cost ₹600 and 3 adult + 2 child cost ₹700 gives **2x + 3y = 600** and **3x + 2y = 700**.", "Taxi fare = fixed ₹x + ₹y per km: 6 km for ₹122 and 8 km for ₹160 give x + 6y = 122, x + 8y = 160."]),
 ("h2", "Solving by Substitution"),
 ("steps", [("Step 1", "Express one variable in terms of the other from one equation (choose the easier one)."), ("Step 2", "Substitute this expression into the other equation to get an equation in one variable and solve it."), ("Step 3", "Put the value back to find the other variable."), ("Step 4", "Verify the pair in both original equations.")]),
 ("p", "Example: 2x + y = 11 and x − 3y = −5. From the first, y = 11 − 2x. Then x − 3(11 − 2x) = −5 gives 7x = 28, so **x = 4**, **y = 3**."),
 ("h2", "Solving by Elimination"),
 ("steps", [("Step 1", "Multiply the equations by suitable numbers so that the coefficients of one variable become equal."), ("Step 2", "Add or subtract the equations to eliminate that variable."), ("Step 3", "Solve the resulting equation and substitute back."), ("Step 4", "Check in both equations.")]),
 ("p", "Example: 3x + 4y = 18 and 5x − 2y = 4. Multiply the second by 2: 10x − 4y = 8. Adding: 13x = 26, so **x = 2**, then **y = 3**."),
 ("note", "NOTE", "If the coefficients of x and y are **interchanged** in the two equations (9x + 7y = 107 and 7x + 9y = 101), add them and subtract them to get x + y and x − y directly."),
 ("h2", "Modelling Word Problems"),
 ("table", ["Type", "Variables", "Equations"], [["Digits", "tens x, units y", "x + y = sum; (10x + y) ∓ (10y + x) = difference"], ["Ages", "present ages", "‘n years ago/after’ shifts both ages by n"], ["Fixed + per unit", "fixed x, rate y", "x + (units)·y = total (twice)"], ["Ratios of income/expense", "incomes 9x, 7x; expenses 4y, 3y", "income − expense = saving for each"], ["Geometry", "length l, width w", "l + w = half-perimeter; l − w = difference"]]),
 ("note", "IMPORTANT", "Always **define the variables**, write two equations, solve, and finish by **checking against the story** (not only the equations)."),
 ("h2", "How Many Solutions? The Ratio Test"),
 ("table", ["Ratios", "Lines", "Number of solutions", "Elimination result"], [["a₁/a₂ ≠ b₁/b₂", "Intersect at one point", "Unique solution", "A variable remains"], ["a₁/a₂ = b₁/b₂ = c₁/c₂", "Coincident", "Infinitely many", "0 = 0"], ["a₁/a₂ = b₁/b₂ ≠ c₁/c₂", "Parallel", "No solution", "A false statement like 0 = 5"]]),
 ("ul", ["x − y = 10 and 10x − 10y = 100: second equation is 10 × first, so infinitely many solutions.", "x − y = 10 and 10x − 10y = 101: after multiplying the first by 10 the left sides agree but 100 ≠ 101, so **no solution**.", "A pair never has exactly two solutions: it has 0, 1 or infinitely many."]),
 ("h2", "Graphical Method"),
 ("steps", [("Step 1", "Make a table of at least two points for each equation (x = 0, y = 0 are handy)."), ("Step 2", "Plot the points on the same axes and draw both lines."), ("Step 3", "Read the common point: its coordinates are the solution."), ("Step 4", "If the lines are parallel there is no solution; if they coincide there are infinitely many.")]),
 ("table", ["Pair", "Graph", "Result"], [["x + 3y = 6, 2x − 3y = 12", "Meet at (6, 0)", "Unique: x = 6, y = 0"], ["x + 2y − 4 = 0, 2x + 4y − 12 = 0", "Parallel (ratios ½ = ½ ≠ ⅓)", "No solution"], ["2x + 3y = 9, 4x + 6y = 18", "Same line", "Infinitely many"]]),
 ("h2", "Using the Ideas"),
 ("ul", ["**Celsius–Fahrenheit:** F = (9/5)C + 32. 30 °C = 86 °F, 95 °F = 35 °C, and the two scales agree at **−40**.", "**Mobile plans:** A = ₹50 + 0.20 per minute, B = ₹30 + 0.30 per minute. Equal when 50 + 0.2t = 30 + 0.3t, i.e. at t = 200 minutes; A is cheaper beyond that.", "**x-intercept** of y = mx + d is **−d/m** (m ≠ 0)."]),
 ("qa", [("What is the slope of a line through (x₁, y₁) and (x₂, y₂)?", "(y₂ − y₁)/(x₂ − x₁), and it is the same for every pair of points on the line."), ("How can you tell without graphing that a pair has no solution?", "a₁/a₂ = b₁/b₂ ≠ c₁/c₂: the lines are parallel."), ("Why can a linear equation in two variables not have only one solution?", "For every value of x we get a matching y, so there are infinitely many solutions forming a line."), ("What does c = 0 tell you about the line?", "It passes through the origin."), ("Which method suits 9x + 7y = 107 and 7x + 9y = 101?", "Add and subtract the equations to get x + y and x − y.")]),
 ],
 takeaways=["A linear equation **ax + by + c = 0** has **infinitely many** solutions, whose graph is a **straight line**.", "**Slope = rise/run = (y₂ − y₁)/(x₂ − x₁)**; in **y = mx + d**, m is the slope and d the y-intercept.", "Horizontal lines have slope **0**; vertical lines have **undefined** slope.", "A pair of linear equations is solved by **substitution**, **elimination** or **graphs**, and the answer is checked in both equations.", "**a₁/a₂ ≠ b₁/b₂** → unique solution; **= c₁/c₂** → infinitely many; **≠ c₁/c₂** → no solution.", "In word problems define variables, form **two equations**, solve and **verify with the story**."])
